<script setup lang="ts">
import {ref,reactive} from 'vue';import {money,type Product} from '@briochett/contracts';import {useAuth} from '../stores/auth';import {api,errorMessage} from '../api';import {useList} from '../composables';import PageHeader from '../components/PageHeader.vue';import Pagination from '../components/Pagination.vue';import AppModal from '../components/AppModal.vue';
const auth=useAuth(),{data,page,busy,error,load}=useList<Product>(()=>'/products'),open=ref(false),selected=ref<Product|null>(null),saving=ref(false),formError=ref(''),form=reactive({name:'',sku:'',priceUsd:'',active:true});
function edit(p:Product|null){selected.value=p;Object.assign(form,p?{name:p.name,sku:p.sku,priceUsd:p.priceUsd,active:p.active}:{name:'',sku:'',priceUsd:'',active:true});formError.value='';open.value=true;}
async function save(){saving.value=true;formError.value='';try{await api(selected.value?'/products/'+selected.value.id:'/products',{method:selected.value?'PATCH':'POST',body:{...form,priceUsd:String(form.priceUsd)}});open.value=false;load();}catch(e){formError.value=errorMessage(e);}finally{saving.value=false;}}
</script>
<template><PageHeader title="Productos" description="Catálogo y precios base en dólares" /><div class="toolbar"><button v-if="auth.isAdmin" @click="edit(null)">+ Nuevo producto</button></div><p v-if="error" class="notice error" role="alert">{{error}}</p><section class="card"><h2>Catálogo de productos</h2><div class="table-wrap"><table v-responsive-table><thead><tr><th>Producto</th><th>Código</th><th>Precio USD</th><th>Estado</th><th v-if="auth.isAdmin">Acciones</th></tr></thead><tbody><tr v-for="p in data.items" :key="p.id"><td class="strong">{{p.name}}</td><td>{{p.sku}}</td><td>{{money(p.priceUsd,'USD')}}</td><td>{{p.active?'Activo':'Inactivo'}}</td><td v-if="auth.isAdmin"><button class="secondary compact" @click="edit(p)">Editar</button></td></tr></tbody></table></div><p v-if="!busy&&!data.items.length" class="empty">Aún no hay productos en el catálogo.</p><Pagination :page="page" :total="data.total" :busy="busy" @change="page=$event" /></section><AppModal v-if="open" :title="selected?'Editar producto':'Nuevo producto'" :busy="saving" @close="open=false"><form class="stack" @submit.prevent="save"><label>Nombre<input v-model="form.name" required maxlength="150" /></label><label>Código de producto<input v-model="form.sku" required maxlength="40" /></label><label>Precio base USD<input v-model="form.priceUsd" type="number" min="0.01" max="9999999.99" step="0.01" required /></label><label class="check"><input v-model="form.active" type="checkbox" /> Producto activo</label><p v-if="formError" class="notice error" role="alert">{{formError}}</p><button :disabled="saving">{{saving?'Guardando…':'Guardar producto'}}</button></form></AppModal></template>
